<script setup lang="ts">
import {ref,onMounted} from 'vue';import {admin,money,date} from '../../../shared/api';import type {Dashboard,AiStatistics} from '../../../shared/adminTypes';import type {Page,Order} from '../../../shared/types';import {useLoad} from '../../../shared/useLoad'
const ai=ref<AiStatistics>(),aiError=ref('');
// AI 暂时不可用时保留交易工作台，用“不可用”明确区分零条会话。
async function loadAi(){ai.value=undefined;aiError.value='';try{ai.value=await admin<AiStatistics>('GET','/admin/ai/statistics')}catch{aiError.value='AI 统计暂不可用，请到 AI 统计页面重试'}}
const data=ref<Dashboard>(),orders=ref<Order[]>([]),{loading,error,run}=useLoad();const load=()=>{void loadAi();return run(async()=>{const [d,o]=await Promise.all([admin<Dashboard>('GET','/admin/dashboard'),admin<Page<Order>>('GET','/admin/orders',undefined,{status:'pending_confirmation',pageSize:5})]);data.value=d;orders.value=o.items})};onMounted(load)
</script>
<template><p class="eyebrow">HELLO, STORE OWNER</p><h2>每一份托付，认真照顾。</h2><p>今天有 {{data?.pendingTasks.appointmentCount||0}} 笔预约待确认、{{data?.pendingTasks.arrivalCount||0}} 笔待到店、{{data?.pendingTasks.afterSaleReviewCount||0}} 笔售后待审核。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-skeleton v-if="loading&&!data" animated :rows="5"/><template v-if="data"><div class="metrics"><article v-for="item in [['今日收款',money(data.grossSalesAmount),'微信实收及线下收款登记'],['今日订单',data.createdOrderCount,`${data.paidOrderCount} 笔已支付`],['在售宠物',data.onSalePetCount,'当前可售个体'],['AI 会话',ai?ai.totals.sessionCount:aiError?'不可用':'加载中','今日有提问的会话']]" :key="item[0]" class="metric"><p>{{item[0]}}</p><strong>{{item[1]}}</strong><small>{{item[2]}}</small></article></div><el-alert v-if="aiError" :title="aiError" type="warning" :closable="false"/><div class="toolbar"><el-button @click="$router.push('/ai-statistics')">查看 AI 统计</el-button><el-button type="primary" size="large" @click="$router.push('/orders')">查看到店预约</el-button><el-button size="large" @click="$router.push('/pets/new')">发布宠物</el-button><el-button size="large" @click="$router.push('/after-sales')">处理售后</el-button><el-button text :loading="loading" @click="load">刷新</el-button></div><h3>待确认预约</h3><div class="table-panel"><el-table :data="orders" empty-text="当前没有待确认预约"><el-table-column label="订单 / 宠物" min-width="240"><template #default="{row}">{{row.orderNo}} · {{row.product.name}}</template></el-table-column><el-table-column prop="contactName" label="联系人" min-width="120"/><el-table-column label="到店金额" min-width="120"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="statusText" label="状态" min-width="110"/><el-table-column label="操作" width="130"><template #default><el-button link type="primary" @click="$router.push('/orders')">处理预约</el-button></template></el-table-column></el-table></div><p class="small muted" style="margin-top:20px">更新时间 {{date(data.updatedAt)}}</p></template></template>
